+package com.example;
+
+import java.util.List;
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern
+            .compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final MessageService service;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<MessageService.Entry> grid = new Grid<>();
+    private boolean resetting;
+
+    public ContactView(MessageService service) {
+        this.service = service;
+        email.setManualValidation(true);
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+        add(name, email, phone, message, send);
+
+        for (var f : List.of(name, email, phone, message)) {
+            f.addValueChangeListener(e -> {
+                if (!resetting) {
+                    send.setEnabled(true);
+                }
+            });
+        }
+        send.addClickListener(e -> submit());
+        send.addClickShortcut(Key.ENTER);
+
+        grid.addColumn(MessageService.Entry::name).setHeader("Name");
+        grid.addColumn(MessageService.Entry::message).setHeader("Message");
+        grid.setItems(service.list());
+        add(grid);
+    }
+
+    private void submit() {
+        for (var f : List.of(name, email, phone, message)) {
+            ((com.vaadin.flow.component.HasValidation) f).setInvalid(false);
+        }
+        String n = name.getValue(), em = email.getValue(),
+                ph = phone.getValue(), msg = message.getValue();
+        boolean ok = true;
+        if (n == null || n.isBlank()) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            ok = false;
+        }
+        boolean hasEmail = em != null && !em.isBlank();
+        boolean hasPhone = ph != null && !ph.isBlank();
+        if (hasEmail && !EMAIL.matcher(em.trim()).matches()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            ok = false;
+        } else if (!hasEmail && !hasPhone) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            ok = false;
+        }
+        if (msg == null || msg.isBlank()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            ok = false;
+        } else if (msg.length() > 500) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+            ok = false;
+        }
+        if (!ok) {
+            return;
+        }
+        service.add(new MessageService.Entry(n, em, ph, msg));
+        grid.setItems(service.list());
+        resetting = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            resetting = false;
+        }
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean dirty() {
+        return !(name.isEmpty() && email.isEmpty() && phone.isEmpty()
+                && message.isEmpty());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!dirty()) {
+            return;
+        }
+        var action = event.postpone();
+        Dialog d = new Dialog();
+        d.setHeaderTitle("Discard changes?");
+        d.add("You have unsent text in the form.");
+        Button keep = new Button("Keep editing", e -> d.close());
+        Button discard = new Button("Discard", e -> {
+            d.close();
+            action.proceed();
+        });
+        d.getFooter().add(keep, discard);
+        d.open();
+    }
+}
